<?php
declare(strict_types=1);
$profileRows = is_array($complianceData['templates'] ?? null) ? $complianceData['templates'] : [];
$profileState = is_array($activeModuleFormState ?? null) ? $activeModuleFormState : [];
$profileFailedAction = (string) ($profileState['action'] ?? '');
$profileFailedInput = is_array($profileState['input'] ?? null) ? $profileState['input'] : [];
$profileValue = static fn (string $key, string $fallback = ''): string => (string) ($profileFailedInput[$key] ?? $fallback);
$profileOpen = static fn (string $action): string => $profileFailedAction === $action ? ' data-record-modal-open-on-load' : '';
$selectedVersionKey = trim((string) ($_GET['template_version'] ?? ''));
if ($selectedVersionKey === '' && $profileRows !== []) $selectedVersionKey = (string) ($profileRows[0]['template_version_key'] ?? '');
$selectedProfile = null;
foreach ($profileRows as $row) if ((string) ($row['template_version_key'] ?? '') === $selectedVersionKey) { $selectedProfile = $row; break; }
?>
